// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Alert } from "@/registry/erbium/ui/alert";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Alert, AlertDescription, AlertTitle } from \"@/registry/erbium/ui/alert\";\nimport type * as React from \"react\";\nimport { alertContent } from \"../helpers\";\n\nconst Example = (args: React.ComponentProps<typeof Alert>) => {\n  const content = alertContent[args.variant ?? \"default\"];\n\n  return (\n    <Alert {...args} className={`w-96 ${args.className ?? \"\"}`}>\n      <AlertTitle>{content.title}</AlertTitle>\n      <AlertDescription>{content.description}</AlertDescription>\n    </Alert>\n  );\n};\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/alert-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import ErrorVariantExample from "./variants/error-variant";

const ErrorVariantSource = "import ExampleAlertError from \"../examples/alert-error\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleAlertError />\n  </div>\n);\n\nexport default Example;\n";

import BasicExample from "./variants/basic";

const BasicSource = "import { Alert, AlertDescription, AlertTitle } from \"@/registry/erbium/ui/alert\";\n\nconst Example = () => (\n  <Alert className=\"w-80\">\n    <AlertTitle>Workspace connected</AlertTitle>\n    <AlertDescription>The agent can read the files in this project.</AlertDescription>\n  </Alert>\n);\n\nexport default Example;\n";

import InfoExample from "./variants/info";

const InfoSource = "import { Alert, AlertDescription, AlertTitle } from \"@/registry/erbium/ui/alert\";\n\nconst Example = () => (\n  <Alert variant=\"info\" className=\"w-96\">\n    <AlertTitle>Plan ready</AlertTitle>\n    <AlertDescription>\n      The agent identified three files to update before writing code.\n    </AlertDescription>\n  </Alert>\n);\n\nexport default Example;\n";

import SuccessExample from "./variants/success";

const SuccessSource = "import { Alert, AlertDescription, AlertTitle } from \"@/registry/erbium/ui/alert\";\n\nconst Example = () => (\n  <Alert variant=\"success\" className=\"w-96\">\n    <AlertTitle>Verification passed</AlertTitle>\n    <AlertDescription>Type checks and 42 tests passed after the changes.</AlertDescription>\n  </Alert>\n);\n\nexport default Example;\n";

import ActionExample from "./variants/action";

const ActionSource = "import { Alert, AlertAction, AlertDescription, AlertTitle } from \"@/registry/erbium/ui/alert\";\nimport { Button } from \"@/registry/erbium/ui/button\";\n\nconst Example = () => (\n  <Alert variant=\"warning\" className=\"w-96\">\n    <AlertTitle>Approval required</AlertTitle>\n    <AlertDescription>The agent needs permission to install a new dependency.</AlertDescription>\n    <AlertAction>\n      <Button size=\"sm\" variant=\"outline\">\n        Review\n      </Button>\n    </AlertAction>\n  </Alert>\n);\n\nexport default Example;\n";

import WarningExample from "./variants/warning";

const WarningSource = "import AlertColors from \"../examples/alert-colors\";\n\nconst Example = () => <AlertColors />;\n\nexport default Example;\n";

const meta = {
  component: Alert,
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nDisplays a callout for agent activity, decisions, and failures. Each variant supplies its own icon.\n\n**Import:** `@/registry/erbium/ui/alert`\n\n## Usage\n\n```tsx\nimport { Alert, AlertAction, AlertDescription, AlertTitle } from \"@/registry/erbium/ui/alert\";\n```\n\n```tsx\n<Alert variant=\"warning\">\n  <AlertTitle>Approval required</AlertTitle>\n  <AlertDescription>The agent needs permission to install a new dependency.</AlertDescription>\n  <AlertAction>\n    <Button variant=\"outline\">Review</Button>\n  </AlertAction>\n</Alert>\n```\n\n## Composition\n\nUse the following composition to build an `Alert`:\n\n```text\nAlert\n├── AlertTitle\n├── AlertDescription\n└── AlertAction\n```",
      },
    },
  },
} satisfies Meta<typeof Alert>;

export default { ...meta, title: "Components/Alert",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Alert> = {
  args: { variant: "default", className: "" },
  argTypes: {
    variant: {
      control: "select",
      options: ["default", "error", "info", "success", "warning"],
    },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const ErrorVariant: Story = {
  name: "Error",
  parameters: {
    docs: {
      description: { story: "Use `variant=\"error\"` when an agent action fails." },
      source: { code: ErrorVariantSource },
    },
  },
  render: ErrorVariantExample,
};

export const Basic: Story = {
  parameters: {
    docs: {
      description: { story: "The default alert reports neutral workspace status." },
      source: { code: BasicSource },
    },
  },
  render: BasicExample,
};

export const Info: Story = {
  parameters: {
    docs: {
      description: { story: "Use `variant=\"info\"` for useful agent progress updates." },
      source: { code: InfoSource },
    },
  },
  render: InfoExample,
};

export const Success: Story = {
  parameters: {
    docs: {
      description: { story: "Use `variant=\"success\"` when a task or verification step completes." },
      source: { code: SuccessSource },
    },
  },
  render: SuccessExample,
};

export const Action: Story = {
  parameters: {
    docs: {
      description: { story: "Use `AlertAction` to add a button or other action element to the alert." },
      source: { code: ActionSource },
    },
  },
  render: ActionExample,
};

export const Warning: Story = {
  parameters: {
    docs: {
      description: { story: "Use `variant=\"warning\"` when the agent may need attention soon." },
      source: { code: WarningSource },
    },
  },
  render: WarningExample,
};

import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";

export default function AlertColors() {
  return (
    <Alert variant="warning" className="max-w-md">
      <AlertTitle>Context window nearly full</AlertTitle>
      <AlertDescription>
        The agent may need to summarize this conversation before continuing the task.
      </AlertDescription>
    </Alert>
  );
}

import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";

export default function AlertError() {
  return (
    <Alert variant="error">
      <AlertTitle>Tool call failed</AlertTitle>
      <AlertDescription>
        The agent could not run the test suite. The workspace process exited before returning
        results.
      </AlertDescription>
    </Alert>
  );
}

export const alertContent = {
  default: {
    title: "Workspace connected",
    description: "The agent can read the app and package files for this task.",
  },
  error: {
    title: "Tool call failed",
    description: "The agent could not run the test suite. Check the workspace process.",
  },
  info: {
    title: "Plan ready",
    description: "The agent identified three files to update before writing code.",
  },
  success: {
    title: "Verification passed",
    description: "Type checks and 42 tests passed after the changes.",
  },
  warning: {
    title: "Approval required",
    description: "The agent needs permission to install a new dependency.",
  },
};

import { Alert, AlertAction, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";
import { Button } from "@/registry/erbium/ui/button";

const Example = () => (
  <Alert variant="warning" className="w-96">
    <AlertTitle>Approval required</AlertTitle>
    <AlertDescription>The agent needs permission to install a new dependency.</AlertDescription>
    <AlertAction>
      <Button size="sm" variant="outline">
        Review
      </Button>
    </AlertAction>
  </Alert>
);

export default Example;

import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";

const Example = () => (
  <Alert className="w-80">
