import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";
import type * as React from "react";
import { alertContent } from "../helpers";

const Example = (args: React.ComponentProps<typeof Alert>) => {
  const content = alertContent[args.variant ?? "default"];

  return (
    <Alert {...args} className={`w-96 ${args.className ?? ""}`}>
      <AlertTitle>{content.title}</AlertTitle>
      <AlertDescription>{content.description}</AlertDescription>
    </Alert>
  );
};

export default Example;

import { Alert, AlertDescription, AlertTitle } from "@/registry/erbium/ui/alert";

const Example = () => (
  <Alert variant="success" className="w-96">
    <AlertTitle>Verification passed</AlertTitle>
    <AlertDescription>Type checks and 42 tests passed after the changes.</AlertDescription>
  </Alert>
);

export default Example;

import AlertColors from "../examples/alert-colors";

const Example = () => <AlertColors />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}
